// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(this)); }

    function testFuzz_property(uint128 amt, address actor) public {
        uint256 amount = bound(uint256(amt), 0, 10 ether);
        vm.assume(actor != address(0));

        vm.deal(actor, amount);

        vm.prank(actor);
        if (amount > 0) {
            c.Put{value: amount}(0);
        } else {
            c.Put(0);
        }

        bool ok = (LastMsg_Sender() == actor) && (LastMsg_Val() == amount) ;
        assertTrue(ok);
    }

    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message public LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    function LastMsg_Sender() public view returns (address) { return LastMsg.Sender; }
    function LastMsg_Val() public view returns (uint) { return LastMsg.Val; }
}
